export function applyTBCGearTokenSources(db: {
	items: UIItem[];
	zones: { id: number; name: string; expansion: Expansion }[];
	npcs: { id: number; name: string; zoneId: number }[];
}): void {
	for (const src of tbcGearTokenSources) {
		const item = db.items.find(i => i.id === src.gearId);
		if (!item || (item.sources?.length ?? 0) > 0) continue;
		item.sources = [
			UIItemSource.create({
				source: {
					oneofKind: 'drop',
					drop: {
						difficulty: src.difficulty,
						zoneId: src.zoneId,
						npcId: src.npcId,
						category: 'Token',
						otherName: src.tokenName,
					},
				},
			}),
		];
		if (!db.zones.find(z => z.id === src.zoneId)) {
			db.zones.push({ id: src.zoneId, name: 'TBC Raid', expansion: Expansion.ExpansionTbc });
		}
		if (src.npcId && !db.npcs.find(n => n.id === src.npcId)) {
			db.npcs.push({ id: src.npcId, name: src.bossName, zoneId: src.zoneId });
		}
	}
}
